  const basePath = formatFieldPath(error.instancePath ?? error.dataPath);
  if (error.keyword === 'required') {
    const missing = typeof error.params.missingProperty === 'string' ? error.params.missingProperty : '';
    const field = basePath ? `${basePath}.${missing}` : missing;
    return `missing required property "${field}"`;
  }
  const target = basePath || '(root)';
  if (error.keyword === 'type') {
    const rawType = error.params.type;
    const expected = Array.isArray(rawType) ? rawType.join(' | ') : String(rawType).split(',').join(' | ');
    return `property "${target}" must be ${expected}`;
  }

